import type { Permission } from './permission-model';
import type { Role } from './role-model';

export interface RolePermission {
  /**
   * @displayName Role Permission ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Role Permission Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  rolePermissionName: string;
  /**
   * @displayName Allowed
   * @validationRule Required for create/update operations
   */
  allowed: boolean;
  /**
   * @displayName Permission
   * @validationRule Required for create/update operations
   */
  permissionDefinition: Pick<Permission, 'id' | 'permissionName'>;
  /**
   * @displayName Role
   * @validationRule Required for create/update operations
   */
  roleDefinition: Pick<Role, 'id' | 'roleName'>;
}

export const _RolePermission = 'RolePermission' as const;